// Firma autorizada del técnico (imagen fija). Solo se entrega a usuarios con sesión válida de Firebase,
// por eso no está en la carpeta pública del sitio.
// Opcional: FIRMA_TECNICO_EMAILS = correos permitidos separados por coma (si se omite, cualquier usuario con sesión).
const FIRMA_PNG_B64 = "";

const env = (k: string) => (process.env[k] || "").trim();

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default async function handler(req: any, res: any) {
  res.setHeader("Cache-Control", "no-store");
  const projectId = env("FIREBASE_PROJECT_ID") || env("VITE_FIREBASE_PROJECT_ID");
  if (!projectId) return res.status(500).json({ error: "Servidor sin configurar" });
  const token = String(req.headers.authorization || "").replace(/^Bearer\s+/i, "");
  if (!token) return res.status(401).json({ error: "Sin sesión" });
  try {
    const { createRemoteJWKSet, jwtVerify } = await import("jose");
    const JWKS = createRemoteJWKSet(new URL("https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com"));
    const { payload } = await jwtVerify(token, JWKS, { issuer: `https://securetoken.google.com/${projectId}`, audience: projectId });
    const permitidos = env("FIRMA_TECNICO_EMAILS").toLowerCase().split(",").map((s: string) => s.trim()).filter(Boolean);
    if (permitidos.length && !permitidos.includes(String(payload.email || "").toLowerCase())) return res.status(403).json({ error: "Sin permiso" });
  } catch {
    return res.status(401).json({ error: "Sesión inválida" });
  }
  return res.status(200).json({ data: "data:image/png;base64," + FIRMA_PNG_B64 });
}
